{"content": "I've created the login controller with credential validation and JWT token generation. The endpoint accepts POST requests with email and password, validates against stored hashes, and returns a signed JWT.", "files": [{"filename": "login_controller.py", "content": "from flask import Blueprint, request, jsonify
from werkzeug.security import check_password_hash
import jwt
import datetime
from models import User
from config import SECRET_KEY

auth_bp = Blueprint('auth', __name__)

@auth_bp.route('/auth/login', methods=['POST'])
def login():
    data = request.get_json()
    if not data or not data.get('email') or not data.get('password'):
        return jsonify({'error': 'Email and password are required'}), 400
    user = User.query.filter_by(email=data['email']).first()
    if not user or not check_password_hash(user.password_hash, data['password']):
        return jsonify({'error': 'Invalid credentials'}), 401
    token = jwt.encode({
        'user_id': user.id,
        'exp': datetime.datetime.utcnow() + datetime.timedelta(hours=24)
    }, SECRET_KEY, algorithm='HS256')
    return jsonify({'token': token}), 200
"}]}

